	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (creation_date)`,
		fmt.Sprintf("%s$G_L_Register$creation_date", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index creation_date: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
