// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *GLRegister) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := fmt.Sprintf("%s$%s", t.company, GLRegisterTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range gLRegisterSIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, GLRegisterTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: GLRegisterTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, GLRegisterTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

