// CalcSums sets each of the decimal or integer fields to its total over the records matching
// the current filters (CalcSums)
func (t *GLRegister) CalcSums(fieldNames ...string) error {
	tableName := fmt.Sprintf("%s$%s", t.company, GLRegisterTableName)
	where, args := t.buildWhereClause()
	for _, name := range fieldNames {
		var column string
		switch strings.ToLower(name) {
		case "no":
			column = "no"
		case "from_entry_no":
			column = "from_entry_no"
		case "to_entry_no":
			column = "to_entry_no"
		case "from_tax_entry_no":
			column = "from_tax_entry_no"
		case "to_tax_entry_no":
			column = "to_tax_entry_no"
		default:
			return fmt.Errorf("CalcSums: %s is not a decimal or integer field of G_L_Register", name)
		}
		query := t.convertPlaceholders(fmt.Sprintf(`SELECT CAST(COALESCE(SUM(%s), 0) AS TEXT) FROM "%s" WHERE %s`, column, tableName, where), len(args))
		var total string
		if err := t.exec().QueryRow(query, args...).Scan(&total); err != nil {
			return fmt.Errorf("CalcSums G_L_Register.%s: %w", column, err)
		}
		switch column {
		case "no":
			f, err := strconv.ParseFloat(total, 64)
			if err != nil {
				return fmt.Errorf("CalcSums G_L_Register.%s: %w", column, err)
			}
			t.No = int(f)
		case "from_entry_no":
			f, err := strconv.ParseFloat(total, 64)
			if err != nil {
				return fmt.Errorf("CalcSums G_L_Register.%s: %w", column, err)
			}
			t.From_entry_no = int(f)
		case "to_entry_no":
			f, err := strconv.ParseFloat(total, 64)
			if err != nil {
				return fmt.Errorf("CalcSums G_L_Register.%s: %w", column, err)
			}
			t.To_entry_no = int(f)
		case "from_tax_entry_no":
			f, err := strconv.ParseFloat(total, 64)
			if err != nil {
				return fmt.Errorf("CalcSums G_L_Register.%s: %w", column, err)
			}
			t.From_tax_entry_no = int(f)
		case "to_tax_entry_no":
			f, err := strconv.ParseFloat(total, 64)
			if err != nil {
				return fmt.Errorf("CalcSums G_L_Register.%s: %w", column, err)
			}
			t.To_tax_entry_no = int(f)
		}
	}
	return nil
}

// LockTable locks the table until the transaction ends (classic LOCKTABLE): on Postgres a
// table lock (tables.LockTable) and the following reads (Get, FindFirst, FindLast, FindSet)
// lock the rows they read (SELECT … FOR UPDATE); SQLite locks the whole database on write
// anyway. Use it inside a transaction.
func (t *GLRegister) LockTable() {
	if !t.lockForUpdate {
		tables.LockTable(t.db, t.dbType, t.company, GLRegisterTableName)
	}
	t.lockForUpdate = true
}

func (t *GLRegister) forUpdate() string {
	if t.lockForUpdate && t.dbType == database.DBTypePostgres {
		return " FOR UPDATE"
	}
	return ""
}

